  if(Math.random()<.055){let news=[['A wolf pack is reported near the river.','food',.04],['A wagon of iron reaches Greenvale.','metal',-.08],['Heavy rain slows timber carts.','wood',.09],['A travelling fair is expected within the week.','general',-.04]];let [txt,cat,d]=news[Math.floor(Math.random()*news.length)];s.world.market[cat]=Math.max(.65,Math.min(1.65,s.world.market[cat]+d));s.world.news.unshift(`D${s.day}: ${txt}`);s.world.news=s.world.news.slice(0,8);RF.log(s,`World: ${txt}`,'important')}
