RF.V95.slotKey=(id,kind)=>`realmforge_v95_${id}_${kind}`;
RF.V95.hash=function(str){let h=2166136261>>>0;for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(16).padStart(8,'0')};
RF.V95.readIndex=function(){try{let x=JSON.parse(localStorage.getItem(this.INDEX_KEY)||'[]');return Array.isArray(x)?x:[]}catch{return []}};
RF.V95.writeIndex=function(arr){localStorage.setItem(this.INDEX_KEY,JSON.stringify(arr))};
