RF.V95.migrate=function(s){if(!s)return s;['migrateV2','migrateV3','migrateV4','migrateV5','migrateV6','migrateV7','migrateV8','migrateV81','migrateV82','migrateV83','migrateV9','migrateV91','migrateV92','migrateV93','migrateV94'].forEach(k=>{try{if(typeof RF[k]==='function')s=RF[k](s)||s}catch(e){console.warn(k,e)}});s.version=this.SCHEMA;return s};
