RF.V95.loadSlot=function(id){let d=this.readSlot(id);if(!d)return false;localStorage.setItem(this.ACTIVE_KEY,id);RF.state=d.state;RF.state.speed=1;RF.state.paused=false;localStorage.setItem('realmforge_save',JSON.stringify(RF.state));RF.UI.modal=null;RF.UI.tab='world';RF.log(RF.state,`Campaign loaded${d.kind!=='primary'?` from ${d.kind} recovery copy`:''}.`,'important');RF.V95.writeSlot(id,RF.state);RF.UI.render(RF.state);return true};
RF.V95.saveNow=function(){let id=this.activeId();if(!id&&RF.state)id=this.createSlot(RF.state,`${RF.state.player.name} • Campaign`);return this.writeSlot(id,RF.state,null,true)};
RF.V95.backupSummary=function(id){return ['primary','backup','recovery'].map(kind=>{let d=this.decode(localStorage.getItem(this.slotKey(id,kind)));return {kind,ok:!!d,savedAt:d?.savedAt||0}})};

// Install slot-aware save immediately. Ordinary autosaves use verified primary + previous primary backup.
RF.save=function(s){if(!s)return false;let id=RF.V95.activeId();if(!id){id=RF.V95.createSlot(s,`${s.player?.name||'Wanderer'} • Campaign`);return true}return RF.V95.writeSlot(id,s)};

// New characters create a separate slot instead of overwriting the prior campaign.
const v95OldStartNew=RF.startNew;
RF.startNew=function(name,bg,avatar){let s=RF.newGame(name,bg,avatar);RF.state=s;let base=(name||'Wanderer').trim()||'Wanderer',existing=RF.V95.readIndex().filter(x=>x.name.startsWith(base)).length;RF.V95.createSlot(s,`${base} • Campaign ${existing+1}`);RF.UI.tab='world';RF.UI.render(s)};

RF.V95.navItems=[['world','🌍','World'],['map','🗺️','World Map'],['database','📚','Database'],['character','🧍','Character'],['skills','📊','Skills & Crafting'],['inventory','🎒','Pack & Bank'],['quests','📜','Quests'],['shop','🪙','Shop'],['dev','🛠️','Developer'],['options','⚙️','Options & Saves']];
RF.UI.nav=function(){let cur=RF.V95.navItems.find(x=>x[0]===this.tab)||RF.V95.navItems[0];return `<nav class="bottomnav compactNav"><div class="navSelectWrap"><span class="navCurrent">${cur[1]}</span><select data-main-nav aria-label="Navigate Realmforge">${RF.V95.navItems.map(x=>`<option value="${x[0]}" ${this.tab===x[0]?'selected':''}>${x[1]} ${x[2]}</option>`).join('')}</select></div></nav>`};

RF.UI.options=function(s){let active=RF.V95.activeId(),slots=RF.V95.readIndex().sort((a,b)=>b.updated-a.updated);let rows=slots.map(m=>{let b=RF.V95.backupSummary(m.id),health=b.filter(x=>x.ok).length,loc=RF.DATA.locations[m.location]?.name||m.location,date=new Date(m.updated).toLocaleString();return `<div class="saveSlot ${m.id===active?'activeSlot':''}"><div class="saveSlotHead"><div><b>${m.id===active?'▶ ':''}${m.name}</b><small>${m.playerName} • Lv ${m.level} • Day ${m.day} • ${loc}</small><small>Saved ${date} • ${health}/3 recovery copies healthy</small></div><span class="saveShield">${health===3?'🛡️':health>=2?'✅':'⚠️'}</span></div><div class="saveActions"><button data-slot-load="${m.id}" ${m.id===active?'disabled':''}>Load</button><button data-slot-save="${m.id}" ${m.id!==active?'disabled':''}>Save Now</button><button data-slot-rename="${m.id}">Rename</button><button data-slot-delete="${m.id}" class="dangerMini">Delete</button></div></div>`}).join('');return `<section class="card optionsCard"><h2>⚙️ Options & Campaigns</h2><div class="notice good">V9.5 uses verified multi-slot saves. Every active campaign keeps a primary save, the previous good save, and an older recovery snapshot.</div><h3>Current Campaign</h3><div class="grid2"><button class="action primary" data-save-now><b>💾 Save Now</b><small>Create and verify a fresh recovery point</small></button><button class="action" data-new-campaign><b>✨ New Campaign</b><small>Keep this campaign and create another</small></button><button class="action" data-export><b>📤 Export Backup</b><small>Portable text backup</small></button><button class="action" data-import><b>📥 Import Backup</b><small>Import as a new campaign slot</small></button><button class="action danger" data-restart-campaign><b>♻️ Restart Campaign</b><small>Archive this campaign first, then restart it</small></button></div><h3>Save Slots</h3><div class="saveSlots">${rows||'<div class="sub">No campaign slots yet.</div>'}</div><div class="sub saveFoot">Tip: keep an occasional exported backup outside the browser too. Slot recovery protects against local corruption; an export protects against clearing browser/app storage.</div></section>`};
const v95PageBase=RF.UI.page.bind(RF.UI);RF.UI.page=function(s){if(this.tab==='options')return this.options(s);return v95PageBase(s)};

const v95ModalBase=RF.UI.modalHtml.bind(RF.UI);RF.UI.modalHtml=function(s){let m=this.modal;if(m?.type==='confirmV95')return `<div class="modalBack"><div class="modal"><h2>${m.title}</h2><div class="sub">${m.text}</div><div class="choices"><button class="choice ${m.danger?'dangerChoice':''}" data-v95-confirm><b>${m.confirm||'Confirm'}</b></button><button class="choice" data-v95-cancel><b>Cancel</b></button></div></div></div>`;if(m?.type==='renameV95')return `<div class="modalBack"><div class="modal"><h2>Rename Campaign</h2><div class="field"><label>Save name</label><input data-v95-rename-input maxlength="40" value="${(m.name||'').replaceAll('&','&amp;').replaceAll('"','&quot;')}"></div><div class="choices"><button class="choice" data-v95-rename-save><b>Save Name</b></button><button class="choice" data-v95-cancel><b>Cancel</b></button></div></div></div>`;return v95ModalBase(s)};

RF.V95.confirm=function(title,text,action,data={},danger=false,confirm='Confirm'){RF.UI.modal={type:'confirmV95',title,text,action,data,danger,confirm};RF.UI.render(RF.state)};
