  clothier:{loot:[7,15],itemChance:.18,quickRolls:1,deepRolls:1,entryBounty:40,lockBounty:48,caughtBounty:65,recommended:6,lockWindow:50,lockRev:1.50,lockStroke:8,label:'Tricky'},
