V.escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
V.escapeRegex=v=>String(v??'').replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
